"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["91920"],{74177(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.dominio_nao_comporta_os_valores","status":422,"titulo":"O dom\xednio novo n\xe3o comporta os valores do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.dominio_nao_comporta_os_valores","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) com um tipo de dado (`dominio`) que n\xe3o comporta os valores que o fato j\xe1 tem cadastrados no cat\xe1logo. S\xf3 o fato categ\xf3rico tem valores; mudar para outro tipo de dado descartaria os valores, e a API n\xe3o os descarta em sil\xeancio. Desativar os valores n\xe3o resolve: o c\xf3digo de um valor nunca \xe9 removido do fato, e os valores desativados contam. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159.","A recusa vem na lista `errors` da resposta, com `field` igual a `dominio`. Nada \xe9 gravado."],"comoResolver":["Mantenha o tipo de dado categ\xf3rico e envie de novo a defini\xe7\xe3o com as demais altera\xe7\xf5es que voc\xea quer. Se o fato precisa mesmo deixar de ser categ\xf3rico, n\xe3o \xe9 poss\xedvel alter\xe1-lo: cadastre um novo fato com o tipo de dado desejado e deixe de usar o atual (desative-o, se nada mais o citar).","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);